const resendHeaders = {
  Authorization: `Bearer ${resendApiKey}`,
  "Content-Type": "application/json"
};
resendHeaders["Idempotency-Key"] = clientIdempotencyKey || "urunk-crm-"+crmId;
const controller = new AbortController();
const timeoutId = setTimeout(() => controller.abort(), RESEND_TIMEOUT_MS);
inFlightSubmissions.add(payloadFingerprint);
try {
  const providerRes = await fetchImpl(RESEND_ENDPOINT, {
    method: "POST",
    headers: resendHeaders,
    body: JSON.stringify(resendPayload),
    signal: controller.signal
  });
  if (!providerRes.ok) {
    await urunkCrmNotify(env,crmId,providerRes.status>=500?"unknown":"failed");
    logSafeContactEvent("error", {
      status: 502,
      code: "EMAIL_DELIVERY_FAILED",
      providerStatus: providerRes.status,
      source,
      lang,
      durationMs: (options.now ?? Date.now()) - startTime
    });
    return jsonResponse(
      502,
      { ok: false, code: "EMAIL_DELIVERY_FAILED" },
      corsHeaders
    );
  }
  let providerJson = null;
  try {
    providerJson = await providerRes.json();
  } catch {
    providerJson = null;
  }
  const messageId = providerJson && typeof providerJson === "object" && typeof providerJson.id === "string" ? providerJson.id.trim() : "";
  if (!messageId) {
    await urunkCrmNotify(env,crmId,"unknown");
    logSafeContactEvent("error", {
      status: 502,
      code: "INVALID_PROVIDER_RESPONSE",
      providerStatus: providerRes.status,
      source,
      lang,
      durationMs: (options.now ?? Date.now()) - startTime
    });
    return jsonResponse(
      502,
      { ok: false, code: "EMAIL_DELIVERY_FAILED" },
      corsHeaders
    );
  }
  if (clientIdempotencyKey) {
    if (processedIdempotencyKeys.size >= MAX_RATE_LIMIT_KEYS) {
      const oldestKey = processedIdempotencyKeys.keys().next().value;
      if (oldestKey) processedIdempotencyKeys.delete(oldestKey);
    }
    processedIdempotencyKeys.set(clientIdempotencyKey, startTime);
  }
  await urunkCrmNotify(env,crmId,"accepted",messageId.slice(0,128));
  logSafeContactEvent("info", {
    status: 200,
    code: "PROVIDER_ACCEPTED",
    providerStatus: providerRes.status,
    providerMessageId: messageId.slice(0, 64),
    source,
    lang,
    durationMs: (options.now ?? Date.now()) - startTime
  });
  return jsonResponse(200, { ok: true }, corsHeaders);
} catch {
  await urunkCrmNotify(env,crmId,"unknown");
  logSafeContactEvent("error", {
    status: 502,
    code: "EMAIL_DELIVERY_FAILED",
    source,
    lang,
    durationMs: (options.now ?? Date.now()) - startTime
  });
  return jsonResponse(
    502,
    { ok: false, code: "EMAIL_DELIVERY_FAILED" },
    corsHeaders
  );
} finally {
  inFlightSubmissions.delete(payloadFingerprint);
  clearTimeout(timeoutId);
}

inFlightSubmissions.add(payloadFingerprint);
try {
  await urunkSalesQueue(env,crmId,resendPayload,startTime);
  const outcome=await urunkSalesDispatch(env,crmId,options.now??Date.now(),fetchImpl);
  if(outcome.state==="accepted"){
    if(clientIdempotencyKey){
      if(processedIdempotencyKeys.size>=MAX_RATE_LIMIT_KEYS){const k=processedIdempotencyKeys.keys().next().value;if(k)processedIdempotencyKeys.delete(k)}
      processedIdempotencyKeys.set(clientIdempotencyKey,startTime);
    }
    logSafeContactEvent("info",{status:200,code:"PROVIDER_ACCEPTED",source,lang});
    return jsonResponse(200,{ok:true},corsHeaders);
  }
  logSafeContactEvent("warn",{status:502,code:"CRM_SAVED_NOTIFICATION_PENDING",source,lang});
  return jsonResponse(502,{ok:false,code:"EMAIL_DELIVERY_FAILED"},corsHeaders);
} catch {
  await urunkCrmNotify(env,crmId,"unknown");
  logSafeContactEvent("error",{status:502,code:"CRM_SAVED_NOTIFICATION_ERROR",source,lang});
  return jsonResponse(502,{ok:false,code:"EMAIL_DELIVERY_FAILED"},corsHeaders);
} finally {
  inFlightSubmissions.delete(payloadFingerprint);
}
